        if isinstance(value, (int, float)):
            return float(value)
        elif isinstance(value, str):
            # Replace comma with dot for decimal separator
            normalized = value.replace(',', '.')
            return float(normalized)
        else:
            return float(value)

    num_a = to_number(a)
    num_b = to_number(b)

    if num_a > num_b:
        return a
    elif num_b > num_a:
