from collections import Counter

def rearrange_string(s):
    n = len(s)
    if n <= 1:
        return s

    count = Counter(s)
    max_freq = max(count.values())

    if max_freq > (n + 1) // 2:
        return None

    chars = sorted(count.keys(), key=lambda x: count[x], reverse=True)
    result = [''] * n
    idx = 0

    for char in chars:
        for _ in range(count[char]):
            result[idx] = char
            idx += 2
            if idx >= n:
                idx = 1

    return ''.join(result)

