def count_duplic(lst):
    if not lst:
        return ([], [])

    result_values = []
    result_counts = []

    current_value = lst[0]
    current_count = 1

    for i in range(1, len(lst)):
        if lst[i] == current_value:
            current_count += 1
        else:
            result_values.append(current_value)
            result_counts.append(current_count)
            current_value = lst[i]
            current_count = 1

    # Append the last group
    result_values.append(current_value)
    result_counts.append(current_count)

    return (result_values, result_counts)

